public void pop(String descriptor) throws InvalidDescriptorException {

    // Parse the descriptor to determine the number of elements to pop
    ParseResult parseResult = this.parseDescriptor(descriptor);
    int numElementsToPop = parseResult.getNumElementsToPop();

    // Pop the elements from the output frame stack
    for (int i = 0; i < numElementsToPop; i++) {
        this.peekFrame().pop();
    }

