    List<E> edges = new ArrayList<>(tour);
    List<V> vertices = new ArrayList<>();
    V startVertex = null;
    V endVertex = null;

    for (E edge : edges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (!vertices.contains(source)) {
            vertices.add(source);
            if (startVertex == null) {
                startVertex = source;
            }
        }

        if (!vertices.contains(target)) {
            vertices.add(target);
            if (endVertex == null) {
                endVertex = target;
            }
        }
    }

    GraphPath<V, E> path = new GraphWalk<>(graph, startVertex, edges, 0);

    return path;
}
